module top_mcu_pll_sram_multiclk_soc ( ref_clk, rst_n, start, uart_rxd, 
        aes_key_ext, aes_pt_ext, aes_vec_valid, uart_txd, done, pass, clk_fast, 
        clk_div2, clk_div4, clk_div8, test_mode, scan_en, scan_in, scan_out );
  input [127:0] aes_key_ext;
  input [127:0] aes_pt_ext;
  input ref_clk, rst_n, start, uart_rxd, aes_vec_valid, test_mode, scan_en,
         scan_in;
  output uart_txd, done, pass, clk_fast, clk_div2, clk_div4, clk_div8,
         scan_out;
  wire   N0, N1, N2, N3, N4, N5, N6, N7, N8, N9, pll_clk_fast, N10, N11,
         pll_clk_div2, N12, N13, pll_clk_div4, N14, N15, clk_div8_func, mem_cs,
         mem_we, mem_oe;
  wire   [9:0] mem_addr;
  wire   [7:0] mem_wdata;
  wire   [7:0] mem_rdata;

  PLL u_pll ( .FB_CLK(1'b0), .FB_MODE(1'b0), .PLL_BYPASS(1'b0), .REF_CLK(
        ref_clk), .CLK_1X(pll_clk_div4), .CLK_2X(pll_clk_div2), .CLK_4X(
        pll_clk_fast) );
  clk_div2_toggle u_div8 ( .clk_in(clk_div4), .rst_n(rst_n), .clk_out(
        clk_div8_func) );
  sram_wrap_1rw1024x8 u_mem ( .clk(clk_div2), .cs(mem_cs), .we(mem_we), .oe(
        mem_oe), .addr(mem_addr), .wdata(mem_wdata), .rdata(mem_rdata) );
  soc_ctrl_multiclk_soc u_ctrl ( .clk_fast(clk_fast), .clk_div2(clk_div2), 
        .clk_div4(clk_div4), .clk_div8(clk_div8), .rst_n(rst_n), .start_ext(
        start), .uart_rxd(uart_rxd), .aes_key_ext(aes_key_ext), .aes_pt_ext(
        aes_pt_ext), .aes_vec_valid(aes_vec_valid), .uart_txd(uart_txd), 
        .done(done), .pass(pass), .mem_cs(mem_cs), .mem_we(mem_we), .mem_oe(
        mem_oe), .mem_addr(mem_addr), .mem_wdata(mem_wdata), .mem_rdata(
        mem_rdata), .test_mode(test_mode), .scan_en(scan_en), .scan_in(scan_in), .scan_out(scan_out) );
  SELECT_OP C29 ( .DATA1(ref_clk), .DATA2(pll_clk_fast), .CONTROL1(N0), 
        .CONTROL2(N1), .Z(clk_fast) );
  GTECH_BUF B_0 ( .A(N9), .Z(N0) );
  GTECH_BUF B_1 ( .A(N8), .Z(N1) );
  SELECT_OP C30 ( .DATA1(ref_clk), .DATA2(pll_clk_div2), .CONTROL1(N2), 
        .CONTROL2(N3), .Z(clk_div2) );
  GTECH_BUF B_2 ( .A(N11), .Z(N2) );
  GTECH_BUF B_3 ( .A(N10), .Z(N3) );
  SELECT_OP C31 ( .DATA1(ref_clk), .DATA2(pll_clk_div4), .CONTROL1(N4), 
        .CONTROL2(N5), .Z(clk_div4) );
  GTECH_BUF B_4 ( .A(N13), .Z(N4) );
  GTECH_BUF B_5 ( .A(N12), .Z(N5) );
  SELECT_OP C32 ( .DATA1(ref_clk), .DATA2(clk_div8_func), .CONTROL1(N6), 
        .CONTROL2(N7), .Z(clk_div8) );
  GTECH_BUF B_6 ( .A(N15), .Z(N6) );
  GTECH_BUF B_7 ( .A(N14), .Z(N7) );
  GTECH_NOT I_0 ( .A(test_mode), .Z(N8) );
  GTECH_BUF B_8 ( .A(test_mode), .Z(N9) );
  GTECH_NOT I_1 ( .A(test_mode), .Z(N10) );
  GTECH_BUF B_9 ( .A(test_mode), .Z(N11) );
  GTECH_NOT I_2 ( .A(test_mode), .Z(N12) );
  GTECH_BUF B_10 ( .A(test_mode), .Z(N13) );
  GTECH_NOT I_3 ( .A(test_mode), .Z(N14) );
  GTECH_BUF B_11 ( .A(test_mode), .Z(N15) );
endmodule

